def transform(grid):
    h, w = len(grid), len(grid[0])
    color = next(v for row in grid for v in row if v not in (0, 8))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
    r0, c0 = min(r for r, c in pts), min(c for r, c in pts)
    shape = {(r-r0, c-c0) for r, c in pts}

    # Generate rotations and reflections of the marked shape.
    variants = set()
    cur = shape
    for _ in range(4):
        for reflected in (cur, { (r, -c) for r, c in cur }):
            mr = min(r for r, c in reflected)
            mc = min(c for r, c in reflected)
            variants.add(frozenset((r-mr, c-mc) for r, c in reflected))
        cur = {(c, -r) for r, c in cur}

    out = [row[:] for row in grid]
    for shape in variants:
        sh = max(r for r, c in shape) + 1
        sw = max(c for r, c in shape) + 1
        for r in range(h-sh+1):
            for c in range(w-sw+1):
                cells = [(r+dr, c+dc) for dr, dc in shape]
                if all(grid[x][y] == 0 for x, y in cells):
                    for x, y in cells:
                        out[x][y] = color
    return out
